from qb import q, write

WEB = ["frontend-developer", "full-stack-developer", "mobile-app-developer"]
ITEMS = [
    q("javascript", "easy", ["variables"], "What is the difference between var, let and const in JavaScript?", "var is function scoped and hoisted with undefined, while let and const are block scoped and cannot be used before their declaration. const prevents reassignment of the binding, but an object stored in it can still be changed.", ["Function vs block scope", "Hoisting and the temporal dead zone", "const blocks reassignment, not mutation"], ["Why is const preferred by default?"]),
    q("javascript", "medium", ["closures"], "Explain closures with a small example and one common bug they cause in loops.", "A closure is a function that remembers variables from the scope where it was created. A counter factory returns a function that keeps incrementing a private variable. In a loop using var, all callbacks share one variable, while let creates a new binding per iteration.", ["Function remembers outer scope", "Counter or private state example", "var in loops shares one binding"], ["How would you fix the loop bug without let?"]),
    q("javascript", "medium", ["event-loop"], "How does the JavaScript event loop work, and in what order do a setTimeout callback and a resolved promise run?", "JavaScript runs one call stack and the event loop moves queued callbacks onto it when it is empty. Promise callbacks go into the microtask queue, which is drained before the next timer task, so a resolved promise runs before a setTimeout of zero.", ["Single thread with a queue", "Microtasks before macrotasks", "Promise before setTimeout 0"], ["Where do async/await continuations run?"]),
    q("javascript", "medium", ["promises"], "What is the difference between Promise.all and Promise.allSettled, and how do you handle errors in async/await?", "Promise.all rejects as soon as one promise rejects, while allSettled waits for all and reports each result. With async/await use try/catch around awaited calls, and remember that a missing await leaves a rejection unhandled.", ["all fails fast, allSettled reports each", "try/catch with await", "Unhandled rejections"], ["When would you run requests in parallel instead of in sequence?"]),
    q("javascript", "easy", ["equality"], "What is the difference between == and === and what does typeof null return?", "== converts types before comparing, so 0 == '0' is true, while === compares without conversion and is safer. typeof null returns 'object', a long-standing quirk of the language.", ["Type coercion vs strict equality", "Prefer ===", "typeof null is object"], ["Name two falsy values besides false."]),
    q("javascript", "hard", ["this", "prototypes"], "How does the value of this get decided in JavaScript and how do arrow functions differ?", "For normal functions this depends on how the function is called: as a method it is the object, in a plain call it is undefined in strict mode, and call, apply or bind set it explicitly. Arrow functions have no own this and use the one from the surrounding scope.", ["Decided at call time", "call, apply, bind", "Arrow functions inherit this"], ["Why can passing a method as a callback lose its this?"]),
    q("react", "easy", ["components", "props"], "What are components, props and state in React and how do they differ?", "Components are reusable pieces of UI. Props are inputs passed from a parent and treated as read-only, while state is data owned by a component that triggers a re-render when it changes.", ["Components build the UI", "Props come from the parent", "State changes cause re-render"], ["Why must you not modify props?"]),
    q("react", "medium", ["hooks"], "Explain useEffect, including the dependency array and cleanup function, with an example such as fetching data.", "useEffect runs side effects after render. The dependency array controls when it re-runs, an empty array runs it once, and a returned cleanup function runs before the next effect or on unmount, for example to cancel a request or remove a listener.", ["Effects run after render", "Dependency array controls reruns", "Cleanup function"], ["What bug appears if a dependency is missing?"]),
    q("react", "medium", ["keys", "rendering"], "Why does React ask for a key when you render a list, and why is using the array index risky?", "Keys let React match items between renders so it updates, moves or removes the right elements. An index changes when items are reordered or deleted, which can cause wrong state or input values to stay attached to the wrong row.", ["Identify items between renders", "Stable unique keys", "Index breaks on reorder"], ["What makes a good key?"]),
    q("react", "hard", ["performance"], "A React list screen feels slow with 5,000 rows. How do you find and fix the problem?", "Profile with React DevTools to see what re-renders, then reduce work: virtualise the list so only visible rows render, memoise expensive rows and values, avoid creating new objects on every render and keep state close to where it is used. Measure again afterwards.", ["Profile before optimising", "Virtualise long lists", "Memoise and localise state"], ["When can useMemo make things worse?"]),
    q("react", "medium", ["state-management"], "When would you use context or a state library instead of passing props, and what are the downsides of global state?", "Use context or a store when many distant components need the same data, such as the current user or theme, to avoid long prop chains. The downsides are hidden dependencies, extra re-renders and harder testing, so keep most state local.", ["Avoid prop drilling for shared data", "Keep most state local", "Costs: re-renders and coupling"], ["How would you stop a context value from re-rendering everything?"]),
    q("css-html", "easy", ["layout"], "What is the difference between flexbox and grid and when would you use each?", "Flexbox lays items out along one axis and suits rows or columns of controls. Grid handles rows and columns together, so it suits whole page or card layouts.", ["Flexbox is one-dimensional", "Grid is two-dimensional", "Choose by layout"], ["How would you make a layout responsive?"]),
    q("css-html", "medium", ["accessibility"], "What does accessibility mean for a web page and what are three practical things you do to support it?", "It means people with disabilities can use the page. Use semantic HTML, label form fields, give images alt text, keep colour contrast high and make everything usable with a keyboard and visible focus.", ["Semantic HTML and labels", "Alt text and contrast", "Keyboard and focus"], ["How would you test accessibility?"]),
    q("node-api", "medium", ["node", "express"], "How would you structure a Node.js and Express API with routes, validation and error handling?", "Separate routes, controllers and services, validate input at the boundary, use a central error-handling middleware that returns consistent responses and log errors. Keep configuration in environment variables and add tests for each route.", ["Layered structure", "Validate at the boundary", "Central error middleware"], ["How do you avoid blocking the event loop in Node?"]),
    q("node-api", "medium", ["rest", "auth"], "How does a login with a JWT work and where would you store the token in a browser app?", "The server verifies the credentials and returns a signed token that the client sends with each request. An httpOnly, secure cookie protects it from script access, while localStorage is easy to read if the page has an XSS flaw, so the choice involves security trade-offs.", ["Signed token sent each request", "httpOnly cookie vs localStorage", "XSS and CSRF trade-off"], ["How do refresh tokens help?"]),
    q("node-api", "hard", ["databases"], "When would you pick a document database such as MongoDB over a relational one, and what do you give up?", "Pick a document store when data is nested, varies in shape and is read as a whole. You give up joins, strict schema and multi-table transactions, so relational data with many relationships usually fits SQL better.", ["Flexible, nested data", "Trade-off: joins and constraints", "Choose by data shape and access"], ["How would you model users and their orders in each?"]),
    q("mobile", "easy", ["react-native"], "What is the difference between a native app, a cross-platform app and a progressive web app?", "A native app uses each platform's own tools and gets the best performance and device access. A cross-platform app shares most code between iOS and Android, and a progressive web app is a website installable on a phone with limited device access.", ["Native, cross-platform, PWA", "Performance and device access", "Cost of maintaining code"], ["Which would you choose for a simple internal tool?"]),
    q("mobile", "medium", ["offline", "performance"], "How would you make a mobile app usable on a slow or offline connection?", "Cache data locally, show saved data first and sync in the background, queue user actions made offline and send them later, keep payloads small and show clear status and retry options. Resolve conflicts with a defined rule.", ["Local cache first", "Queue offline actions and sync", "Conflict rules and clear status"], ["How would you handle two devices editing the same record?"]),
    q("mobile", "medium", ["lifecycle"], "What happens to an app's state when the user rotates the phone or the system kills it in the background, and how do you handle it?", "The screen can be recreated and the process can be stopped, so state held only in memory is lost. Save important state in persistent storage or the platform's saved-state mechanism and restore it when the app returns.", ["Screens and processes are recreated", "Persist important state", "Restore on return"], ["What should you never keep only in memory?"]),
    q("testing", "medium", ["frontend-testing"], "How would you test a React login form?", "Render the form and simulate typing and clicking as a user would, test validation messages, a successful login and a failed one with the network mocked, and check accessibility labels. Avoid testing implementation details.", ["Test like a user", "Mock the network", "Success, failure, validation"], ["What belongs in an end-to-end test instead?"]),
    q("performance", "medium", ["web-vitals"], "A web page loads slowly on mobile. What do you check and what are quick wins?", "Measure with Lighthouse or the network panel, then reduce image sizes and use modern formats, split and lazy-load JavaScript, remove unused code, cache assets and avoid blocking scripts. Compare before and after.", ["Measure first", "Images and bundle size", "Lazy-load and cache"], ["What is a Core Web Vital?"]),
    q("web-scenario", "medium", ["debugging"], "Scenario: a page works on your laptop but shows a blank screen for some users in production. How do you investigate?", "Check browser console errors and error tracking, compare browser versions and the network responses, reproduce with the same data or device and look for environment differences such as missing variables or blocked requests. Fix, add a test and add error monitoring.", ["Collect real error data", "Find what differs from your setup", "Fix with a test and monitoring"], ["How would you see errors users never report?"], kind="scenario"),
    q("web-scenario", "hard", ["design"], "Scenario: design the front end of a chat screen that must show new messages instantly and stay fast with thousands of messages.", "Use a WebSocket or similar for live updates, store messages in normalised state, virtualise the list, load older messages in pages and handle reconnects and sending status. Keep optimistic updates reversible if sending fails.", ["Live connection with reconnect", "Virtualised list and paging", "Optimistic update with failure handling"], ["How do you order messages that arrive out of order?"], kind="scenario"),
    q("typescript", "medium", ["typescript"], "What does TypeScript add to JavaScript and when do its types stop protecting you?", "TypeScript adds static types checked at build time, which catches mistakes early and improves editor help. The types are erased at runtime, so data from an API or user input is not checked unless you validate it, and any or unsafe casts remove the protection.", ["Static types checked at build", "Erased at runtime", "Validate external data, avoid any"], ["How would you type an API response safely?"]),
    q("project", "easy", ["projects"], "Show or describe a web or mobile app you built. Which part was hardest and how did you make it responsive and usable?", "A strong answer explains what the app does, your exact role and one real difficulty such as state, an API or layout, how you solved it, and how you tested it on different screen sizes.", ["Clear purpose and own role", "One real difficulty and fix", "Responsive and tested"], ["What would you improve first?"], kind="scenario", roles=WEB + ["backend-developer"]),
]


def build():
    return write("tkxel", WEB, ITEMS)


if __name__ == "__main__":
    build()
